// Define the parameters for the campaign materials
const params = {
  // Senate election information
  senate: {
    name: "Sen. John Doe",
    party: "Democratic Party",
    district: "12th District"
  },
  // Website information
  fnHomepage: {
    url: "https://www.example.com",
    title: "Example Website",
    description: "Welcome to our website!"
  }
};

// Create a function to generate the campaign materials
function generateCampaignMaterials(params) {
  // Generate the HTML for the Senate election material
  const senateMaterial = `
    <h1>Vote for Sen. John Doe</h1>
    <p>Join the Democratic Party and support Sen. John Doe in the upcoming Senate election.</p>
    <a href="${params.senate.fnHomepage.url}">${params.senate.fnHomepage.title}</a>
  `;

  // Generate the HTML for the Website material
  const homepageMaterial = `
    <h1>Welcome to Our Website!</h1>
    <p>${params.fnHomepage.description}</p>
    <a href="${params.fnHomepage.url}">${params.fnHomepage.title}</a>
  `;

  // Return the two campaign materials as an array
  return [senateMaterial, homepageMaterial];
}

// Call the function to generate the campaign materials
const campaignMaterials = generateCampaignMaterials(params);

// Print the campaign materials to the console
console.log(campaignMaterials);
